; pic8 -- P2 integer spine (isel-pic18)
    list p=p18f4550
    radix hex

    org 0x0000
    goto __start

    org 0x0008
isr:
    MOVFF 0x000, 0x00C
    MOVFF 0x001, 0x00D
    MOVFF 0x002, 0x00E
    MOVFF 0x003, 0x00F
    MOVFF 0xFD8, 0x001
    MOVFF 0xFE0, 0x002
    MOVFF 0xFE9, 0x003
    MOVFF 0xFEA, 0x004
    MOVFF 0xFF6, 0x005
    MOVFF 0xFF7, 0x006
    MOVFF 0xFF8, 0x007
    MOVWF 0x0004,A
    MOVLW 0x55
    MOVWF 0x081,A
    MOVFF 0x010, 0x01C
    MOVFF 0x01C, 0x01E
    CALL bump_isr
    MOVFF 0x000, 0x01D
    MOVFF 0x01D, 0x010
    MOVFF 0x00F, 0x003
    MOVFF 0x00E, 0x002
    MOVFF 0x00D, 0x001
    MOVFF 0x00C, 0x000
    MOVFF 0x007, 0xFF8
    MOVFF 0x006, 0xFF7
    MOVFF 0x005, 0xFF6
    MOVFF 0x004, 0xFEA
    MOVFF 0x003, 0xFE9
    MOVFF 0x002, 0xFE0
    MOVFF 0x001, 0xFD8
    MOVF 0x0004, W, A
    RETFIE
bump:
    MOVLW 0x01
    ADDWF 0x01A,W,A
    MOVWF 0x01B,A
    MOVF 0x01B,W,A
    MOVWF 0x000,A
    RETURN
main:
    MOVFF 0x011, 0x012
    MOVFF 0x012, 0x010
    MOVLW 0x11
    MOVWF 0x081,A
    MOVFF 0x010, 0x013
    MOVFF 0x013, 0x01A
    CALL bump
    MOVFF 0x000, 0x014
    MOVFF 0x014, 0x010
    MOVFF 0x010, 0x015
    MOVLW 0x01
    ADDWF 0x015,W,A
    MOVWF 0x016,A
    MOVFF 0x016, 0x010
    MOVFF 0x010, 0x017
    MOVLW 0x02
    MOVWF 0x01A,A
    CALL bump
    MOVFF 0x000, 0x018
    MOVF 0x017,W,A
    ADDWF 0x018,W,A
    MOVWF 0x019,A
    MOVFF 0x019, 0x010
    MOVLW 0x22
    MOVWF 0x081,A
    RETURN
bump_isr:
    MOVLW 0x01
    ADDWF 0x01E,W,A
    MOVWF 0x01F,A
    MOVF 0x01F,W,A
    MOVWF 0x000,A
    RETURN
__start:
    call main
    sleep
    end
